  1→// TranslatorsBridgeSubsystem.h
  2→// GameInstanceSubsystem that owns the bridge state machine, file I/O,
  3→// USDA/JSON parsing, behavioral signals, and profile generation.
  4→//
  5→// Phase 4: All game flow logic migrated from BridgeComponent.
  6→// BridgeComponent is now a thin actor-component relay for Blueprint binding.
  7→
  8→#pragma once
  9→
 10→#include "CoreMinimal.h"
 11→#include "Subsystems/GameInstanceSubsystem.h"
 12→#include "Tickable.h"
 13→#include "BridgeTypes.h"
 14→#include "TranslatorsBridgeSubsystem.generated.h"
 15→
 16→UCLASS()
 17→class TRANSLATORSBRIDGERUNTIME_API UTranslatorsBridgeSubsystem
 18→    : public UGameInstanceSubsystem
 19→    , public FTickableGameObject
 20→{
 21→    GENERATED_BODY()
 22→
 23→public:
 24→    // === LIFECYCLE ===
 25→
 26→    virtual void Initialize(FSubsystemCollectionBase& Collection) override;
 27→    virtual void Deinitialize() override;
 28→
 29→    // FTickableGameObject
 30→    virtual void Tick(float DeltaTime) override;
 31→    virtual TStatId GetStatId() const override;
 32→    virtual bool IsTickable() const override { return bIsActive; }
 33→    virtual bool IsTickableInEditor() const override { return false; }
 34→
 35→    // === GAME FLOW ===
 36→
 37→    /** Start the bridge: resolve path, create directory, begin polling */
 38→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge", meta = (ToolTip = "Start the bridge and begin watching for state files"))
 39→    void StartGame();
 40→
 41→    /** Stop the bridge and reset state */
 42→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge", meta = (ToolTip = "Stop the bridge and clean up"))
 43→    void StopGame();
 44→
 45→    /** Submit a player answer (prefers USD, falls back to JSON) */
 46→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge", meta = (ToolTip = "Submit the player's answer for the current question"))
 47→    void SubmitAnswer(const FString& QuestionId, int32 OptionIndex, float ResponseTimeMs);
 48→
 49→    /** Send acknowledgment that UE5 is ready (prefers USD, falls back to JSON) */
 50→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge", meta = (ToolTip = "Acknowledge readiness to the Python bridge"))
 51→    void SendAcknowledge();
 52→
 53→    /** Force reload the USD stage (broadcast for Blueprint handling) */
 54→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge", meta = (ToolTip = "Force USD Stage Actor to reload"))
 55→    void ForceReloadUsdStage();
 56→
 57→    /** Parse cognitive profile from exported USDA file */
 58→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge", meta = (ToolTip = "Parse a cognitive profile from a .usda file"))
 59→    FTranslatorsProfile ParseCognitiveProfile(const FString& UsdPath);
 60→
 61→    // === ACCESSORS ===
 62→
 63→    /** Get the current bridge state */
 64→    UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Translators Bridge")
 65→    ETranslatorsBridgeState GetBridgeState() const { return CurrentState; }
 66→
 67→    /** Get the currently active question */
 68→    UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Translators Bridge")
 69→    FTranslatorsQuestion GetCurrentQuestion() const { return CurrentQuestion; }
 70→
 71→    /** Get accumulated behavioral signals */
 72→    UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Translators Bridge")
 73→    FBehavioralSignals GetBehavioralSignals() const { return Signals; }
 74→
 75→    /** Check if bridge is connected to the Python side */
 76→    UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Translators Bridge")
 77→    bool IsBridgeConnected() const { return CurrentState != ETranslatorsBridgeState::Idle && CurrentState != ETranslatorsBridgeState::Error; }
 78→
 79→    /** Check if using USD mode (v2.0.0) */
 80→    UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Translators Bridge")
 81→    bool IsUsingUsdMode() const { return bUsingUsdMode; }
 82→
 83→    /** Get the bridge exchange directory path */
 84→    UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Translators Bridge")
 85→    FString GetBridgePath() const { return BridgePath; }
 86→
 87→    // === DELEGATES ===
 88→
 89→    /** Fired when Python bridge_orchestrator signals ready */
 90→    UPROPERTY(BlueprintAssignable, Category = "Translators Bridge|Events")
 91→    FOnBridgeReady OnBridgeReady;
 92→
 93→    /** Fired when a new question arrives (fully parsed) */
 94→    UPROPERTY(BlueprintAssignable, Category = "Translators Bridge|Events")
 95→    FOnQuestionReady OnQuestionReady;
 96→
 97→    /** Fired during scene transitions */
 98→    UPROPERTY(BlueprintAssignable, Category = "Translators Bridge|Events")
 99→    FOnTransitionReady OnTransitionReady;
100→
101→    /** Fired when the cognitive profile is complete */
102→    UPROPERTY(BlueprintAssignable, Category = "Translators Bridge|Events")
103→    FOnProfileComplete OnProfileComplete;
104→
105→    /** Fired on any bridge error */
106→    UPROPERTY(BlueprintAssignable, Category = "Translators Bridge|Events")
107→    FOnBridgeError OnBridgeError;
108→
109→    /** Fired when a USD profile file changes on disk */
110→    UPROPERTY(BlueprintAssignable, Category = "Translators Bridge|Events")
111→    FOnUsdProfileUpdated OnUsdProfileUpdated;
112→
113→    // === CONFIGURATION ===
114→
115→    /** Debounce time in seconds for file change detection */
116→    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Translators Bridge|Config", meta = (ClampMin = "0.01", ClampMax = "1.0"))
117→    float DebounceTime = 0.05f;
118→
119→    /** Polling interval in seconds */
120→    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Translators Bridge|Config", meta = (ClampMin = "0.1", ClampMax = "5.0"))
121→    float PollInterval = 0.5f;
122→
123→    /** Enable verbose logging */
124→    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Translators Bridge|Config")
125→    bool bVerboseLogging = false;
126→
127→    /** Notify the subsystem that a file in the bridge directory changed.
128→     *  Called by BridgeEditorSubsystem in editor builds or by external code. */
129→    void NotifyFileChanged(const FString& Filename, bool bIsUsdProfile);
130→
131→private:
132→    // === STATE ===
133→
134→    void SetState(ETranslatorsBridgeState NewState);
135→    FString ResolveBridgePath() const;
136→    FString GetBridgeFilePath(const FString& Filename) const;
137→    void BridgeLog(const FString& Message) const;
138→
139→    // === FILE I/O ===
140→
141→    void ProcessStateFile();
142→    void WriteJsonToFile(const FString& Filename, const TSharedPtr<FJsonObject>& JsonObj);
143→
144→    // === JSON STATE HANDLERS ===
145→
146→    void HandleReadyState(const TSharedPtr<FJsonObject>& JsonObj);
147→    void HandleQuestionState(const TSharedPtr<FJsonObject>& JsonObj);
148→    void HandleTransitionState(const TSharedPtr<FJsonObject>& JsonObj);
149→    void HandleFinaleState(const TSharedPtr<FJsonObject>& JsonObj);
150→
151→    // === USD NATIVE COMMUNICATION (v2.0.0) ===
152→
153→    bool ProcessBridgeStateUsda();
154→    FString ParseUsdaVariant(const FString& Content, const FString& VariantSetName);
155→    FString ParseUsdaAttribute(const FString& Content, const FString& PrimPath, const FString& AttrName);
156→    void HandleUsdaReadyState(const FString& Content);
157→    void HandleUsdaQuestionState(const FString& Content);
158→    void HandleUsdaTransitionState(const FString& Content);
159→    void HandleUsdaFinaleState(const FString& Content);
160→    FString BuildQuestionJson();
161→    FString UpdateUsdaVariant(const FString& Content, const FString& VariantSetName, const FString& NewValue);
162→    FString UpdateUsdaAttribute(const FString& Content, const FString& PrimName, const FString& AttrName, const FString& NewValue, bool bIsString);
163→
164→    // === BEHAVIORAL SIGNALS ===
165→
166→    void UpdateBehavioralSignals(FString& Content, float ResponseTimeMs);
167→
168→    // === DEPTH LABELS ===
169→
170→    static FString GetDepthLabelForIndex(int32 Index);
171→
172→    // === INTERNAL STATE ===
173→
174→    ETranslatorsBridgeState CurrentState = ETranslatorsBridgeState::Idle;
175→    FTranslatorsQuestion CurrentQuestion;
176→    FBehavioralSignals Signals;
177→    FString BridgePath;
178→    FString CurrentStateJson;
179→    bool bIsActive = false;
180→    bool bUsingUsdMode = false;
181→
182→    // Response time history for behavioral signal computation
183→    TArray<float> ResponseTimes;
184→
185→    // Debouncing
186→    float TimeSinceLastStateChange = 0.0f;
187→    bool bStateChangePending = false;
188→    float TimeSinceLastUsdChange = 0.0f;
189→    bool bUsdChangePending = false;
190→
191→    // Polling
192→    float PollTimer = 0.0f;
193→    FDateTime LastStateFileTime;
194→    FDateTime LastUsdFileTime;
195→};
196→

